const SCORING_VERSION = 'qual_v1';
const W_EMAIL = 40;
const W_PREFERRED_EMAIL = 5;
const W_PHONE = 15;
const W_WEBSITE = 10;
const W_LINKEDIN = 10;
const W_SOCIAL = 5;
const W_CLEAN_ENRICHMENT = 5;
const QUALIFY_MIN_SCORE = 55;
const PREFERRED_EMAIL_RE = /^(info|contact|admin|hello|enquiries|enquiry|office|sales|reception|bookings)@/;
const rows = $input.all().map(i => i.json);
const scored = rows.map(r => {
  const enrichment = r.enrichment ?? {};
  const socials = enrichment.socials ?? {};
  const factors = {
    email: r.email ? W_EMAIL : 0,
    preferred_email: (r.email && PREFERRED_EMAIL_RE.test(r.email)) ? W_PREFERRED_EMAIL : 0,
    phone: r.phone ? W_PHONE : 0,
    website: r.website ? W_WEBSITE : 0,
    linkedin: (r.linkedin_url || socials.linkedin) ? W_LINKEDIN : 0,
    social: (socials.facebook || socials.instagram) ? W_SOCIAL : 0,
    clean_enrichment: enrichment.error ? 0 : W_CLEAN_ENRICHMENT,
    segment_priority: Number(r.priority_weight ?? 0)
  };
  const score = Object.values(factors).reduce((a, b) => a + b, 0);
  let new_stage;
  if (r.email && score >= QUALIFY_MIN_SCORE) { new_stage = 'qualified'; }
  else if (!r.email && !r.phone) { new_stage = 'disqualified'; }
  else { new_stage = 'enriched'; }
  return { id: r.id, score, new_stage, qual: { version: SCORING_VERSION, threshold: QUALIFY_MIN_SCORE, factors, decision: new_stage } };
});
return [{ json: { payload: JSON.stringify(scored), scored_count: scored.length } }];
